/* Four connected recording stories. All messages, signatures and charges are local demo data. */
'use strict';
const connectedBase={render,handle,bar:demoBar,overlay:renderOverlay,organizer:organizerPortal,guest:guestPortal,detail:individualDetailPage,list:individualListPage,messages:mailboxMessages,invoice:adminInvoice,totals,quoteLines,wizardBody,captureWizard,header:portalHeader,availability:availabilityBookings};
const ops=()=>state.operations??=( {requests:[],orders:[],cart:[],nextRequest:127,nextOrder:1058,category:'Entrees',addonCategory:'Activities',selectedService:'forest',staff:'Sam Patel',tip:0,discount:0} );
const serviceCatalog=[{id:'forest',title:'Guided Forest Walk',category:'Activities',when:'Fri, Nov 13, 2026 · 9:00 AM',description:'Fri, Nov 13 · 9:00 AM · 90 minutes',price:0,capacity:20,booked:12},{id:'campfire',title:'Evening Campfire',category:'Activities',when:'Sat, Nov 14, 2026 · 8:00 PM',description:'Sat, Nov 14 · 8:00 PM',price:0,capacity:40,booked:10},{id:'spa',title:'Spa massage',category:'Activities',when:'Sat, Nov 14, 2026 · 2:00 PM',description:'Sat, Nov 14 · 2:00 PM · 60 minutes',price:80,capacity:8,booked:2},{id:'canoe',title:'Canoe rental',category:'Activities',when:'Sat, Nov 14, 2026 · 9:00 AM',description:'Any day · 9:00 AM to 5:00 PM',price:30,capacity:10,booked:4},{id:'lunch',title:'Packed lunch',category:'Meals',when:'Sun, Nov 15, 2026 · 10:30 AM',description:'Pick up at the Dining Hall before departure',price:18,capacity:60,booked:0},{id:'transfer',title:'Airport shuttle',category:'Shuttle',when:'Sun, Nov 15, 2026 · 11:30 AM',description:'Main Lodge → airport · one way',price:35,capacity:14,booked:4},{id:'late',title:'Late check-out',category:'Extras',when:'Sun, Nov 15, 2026 · 2:00 PM',description:'Subject to room availability',price:40,capacity:10,booked:0}];
const cent=n=>Math.round(n*100)/100;
const serviceById=id=>serviceCatalog.find(s=>s.id===id);
const guestKey=r=>r.organizerPaid?r.guest.email:r.id;
const requestsFor=r=>ops().requests.filter(q=>q.guestKey===guestKey(r));
const ordersFor=r=>ops().orders.filter(q=>q.guestKey===guestKey(r));
const serviceTotal=r=>cent(requestsFor(r).filter(q=>q.status==='Confirmed').reduce((n,q)=>n+q.amount,0));
const posTotal=r=>cent(ordersFor(r).reduce((n,q)=>n+q.total,0));
const posPaid=r=>cent(ordersFor(r).filter(q=>q.payment!=='Room').reduce((n,q)=>n+q.total,0));
const stayTotal=r=>cent(r.amount+extrasTotal(r)+serviceTotal(r)+posTotal(r));
const stayPaid=r=>cent((r.paid?r.amount:0)+(r.extrasPaid||0)+(r.servicePaid||0)+(r.balancePayment||0)+posPaid(r));
const stayBalance=r=>Math.max(0,cent(stayTotal(r)-stayPaid(r)));
const groupBalance=()=>Math.max(0,cent((v2Active()?groupInvoiceTotal():totals().total)-(state.quote.paid?totals().deposit:0)-(state.quote.balancePaid||0)));
const connectedGuests=()=>[...pickup().reservations,...roomSlots().filter(s=>s.guest&&s.payer==='Organizer').map(organizerPaidGuest)];
const activePosGuest=()=>connectedGuests().find(r=>r.id===(ops().reservationId||'00032'))||connectedGuests().find(r=>r.paid);
const guestPassCode=r=>'CV-'+String(Number(r.id)+380).padStart(4,'0');
function ensureLaterStory(video){if(!v2Active()){startVideo2Sample();state.operations=null;}if(!individualById('00032')){pickup().selectedType=v2Types[1];pickup().invitedSlot=null;payIndividual({first:'Priya',last:'Nair',email:'priya@horizon.example',phone:'+1 415 555 0142',card:'4242424242424242',expiry:'12/29',cvc:'123'});}state.ui.video=video;ops().reservationId='00032';state.ui.portalGuestId='00032';modal=null;save();}
function requestService(id,r=portalGuest()){const s=serviceById(id);requireState(r?.paid&&!r.checkedOut,'Confirm your stay before requesting a service.');requireState(s,'Choose an activity.');requireState(!requestsFor(r).some(q=>q.serviceId===id&&q.status!=='Declined'),'This service has already been requested.');const q={id:'REQ-'+String(ops().nextRequest++).padStart(4,'0'),guestKey:guestKey(r),reservationId:r.id,guest:{...r.guest},unit:r.unit,serviceId:id,title:s.title,when:s.when,amount:cent(s.price*1.1),status:'New',assigned:'Alex Rivera',message:'',history:['Request received · Guest portal','Staff notified · Request Manager']};ops().requests.unshift(q);ops().lastRequest=q.id;r.activities.push('Requested '+s.title+' · '+q.id+'. Staff notified.');save();return q;}
function resolveService(id,status,message,assigned){const q=ops().requests.find(q=>q.id===id);requireState(q&&q.status==='New','This request has already been handled.');const s=serviceById(q.serviceId);if(status==='Confirmed')requireState(s.booked+ops().requests.filter(x=>x.serviceId===s.id&&x.status==='Confirmed').length<s.capacity,'This session is full.');const defaultMessage='Meet at the Main Lodge Lobby at 8:50 AM.';const isDefault=!message||message===defaultMessage||message===q.defaultMessage;q.status=status;q.message=(isDefault?'':message)|| (status==='Confirmed'?'Your activity is confirmed. Meet at the Main Lodge Lobby 10 minutes before departure.':'This activity is unavailable. Please choose another activity.');q.assigned=assigned||'Alex Rivera';q.history.unshift('Request '+status.toLowerCase()+' · '+ops().staff+' · Guest notified');const r=individualById(q.guestKey)||roomSlots().filter(s=>s.guest).map(organizerPaidGuest).find(r=>guestKey(r)===q.guestKey);if(r)r.activities.push(q.title+' '+status.toLowerCase()+'. '+q.message);save();}
function portalIdentity(){const role=portalRole(),person=role==='organizer'?name():portalGuest()?v2Full(portalGuest().guest):v2Full(pickup()?.guestDraft||{});return '<div class="secure-identity"><span>Secure link</span><b>'+esc(person||'Your group stay')+'</b><i>'+esc((person||'Guest').split(' ').map(s=>s[0]).join('').slice(0,2))+'</i></div>';}
portalMenus.organizer=[['Overview','overview'],['Rooms','rooms'],['Guests','guests'],['Documents','documents'],['Invoices','billing'],['Schedule & meals','schedule'],['Invite guests','invite']];
portalMenus.guest=[['My stay','stay'],['Room','room'],['Payment','payment'],['Schedule','schedule'],['Documents','documents'],['Charges','charges'],['Add-ons','extras']];
portalHeader=function(){const role=portalRole();return '<header class="guest-header">'+img('0d92a.svg','Booking Ninjas')+'</header><div class="secure-bar"><nav class="portal-menu" aria-label="'+role+' portal navigation">'+portalMenus[role].map(([title,key])=>'<button class="'+(state.ui.portalPage===key?'active':'')+'" data-action="portal-'+role+'-'+key+'">'+title+'</button>').join('')+'</nav>'+portalIdentity()+'</div>';};
function statCards(cards){return '<div class="pickup-summary">'+cards.map(([label,value,sub,action])=>'<section><small>'+label+'</small><strong>'+value+'</strong><small>'+sub+'</small>'+(action||'')+'</section>').join('')+'</div>';}
function scheduleRows(){const r=state.request,q=state.quote,days=nights(),rows=[];for(let i=0;i<days;i++){const d=addDays(r.start,i);if(i===0)rows.push([dateLabel(d),'3:00 – 5:00 PM','Arrival and check-in','Main Lodge Lobby']);else rows.push([dateLabel(d),'7:30 – 9:00 AM','Breakfast','Dining Hall']);if(i<(q?.spaceDays||days))rows.push([dateLabel(d),i===0?'5:00 – 6:00 PM':i===days-1?'10:00 AM – 12:00 PM':q?.spaceTime||'9:00 AM – 5:00 PM',i===0?'Welcome session':i===days-1?'Closing workshop':'Leadership sessions',q?.space||'Meeting Hall']);if(i>0)rows.push([dateLabel(d),'12:30 – 1:30 PM','Lunch','Dining Hall']);rows.push([dateLabel(d),'6:30 – 8:30 PM','Group dinner','Dining Hall']);}rows.push([dateLabel(r.end),'7:30 – 9:00 AM','Breakfast','Dining Hall'],[dateLabel(r.end),'By 11:00 AM','Check-out','Main Lodge Lobby']);return rows;}
function addDays(d,n){const v=new Date(d+'T12:00:00');v.setDate(v.getDate()+n);return v.toISOString().slice(0,10);}
function mealRows(){const existing=ops().meals||[];const rows=scheduleRows().filter(x=>['Breakfast','Lunch','Group dinner'].includes(x[2])).map(x=>({meal:x[2],when:x[0]+' · '+x[1],guests:state.request.guests,dietary:'4 vegetarian, 2 gluten-free',status:'Confirmed'}));ops().meals=rows.map(x=>{const old=existing.find(y=>y.meal===x.meal&&y.when===x.when);return old?{...x,...old}:x;});return ops().meals;}
organizerPortal=function(){if(!v2Active())return connectedBase.organizer();const page=state.ui.portalPage||'overview',r=state.request,t=totals(),assigned=roomSlots().filter(s=>s.guest).length,open=openSlots().length;let body='',title='';
 if(page==='overview'){title=r.group;body=statCards([['Dates',dateLabel(r.start).replace(', 2026',''),nights()+' nights'],['Rooms',roomSlots().length,assigned+' assigned · '+open+' open',button('Assign rooms','portal-organizer-rooms')],['Balance due',money(groupBalance()),'Due '+dueDate(),button('Pay now','cx-group-pay','primary')],['Meals',r.guests*nights(),'guest-days · '+r.guests+' guests']])+'<div class="portal-overview-columns">'+panel('To do',[['Assign your remaining '+open+' rooms','Add guests, or share the group code so they can book and pay themselves.','Go to rooms','portal-organizer-rooms'],['Pay the balance by '+dueDate(),'INV-00031 · Balance '+money(groupBalance()),'Pay now','cx-group-pay'],['Confirm dietary needs for the group dinner','Fri, Nov 13 · 6:30 PM · Dining Hall','Add details','cx-meals']].map(([a,b,c,d])=>'<div class="portal-todo"><span>○</span><div><b>'+a+'</b><p>'+b+'</p></div>'+button(c,d)+'</div>').join(''))+panel('Next on the schedule',scheduleRows().slice(0,3).map(x=>'<div class="portal-schedule-item"><small>'+x[0]+' · '+x[1]+'</small><b>'+x[2]+'</b><p>'+x[3]+'</p></div>').join(''))+'</div>';}
 else if(page==='guests'){title='Guest list';const slots=roomSlots().filter(s=>s.guest),filter=ops().guestFilter||'All';const rows=slots.filter(s=>filter==='All'||s.status===filter).map(s=>['<b>'+esc(v2Full(s.guest))+'</b><p class="hint">'+esc(s.guest.email)+'</p>',s.type+' · '+s.unit,s.payer,v2Pill(s.status),s.guest.dietary||'—',button(s.status==='Invited'?'Resend':'Edit','v2-slot-'+s.id,'link')]);body='<div class="row mb">'+['All','Assigned','Invited','Paid'].map(x=>button(x+' '+slots.filter(s=>x==='All'||s.status===x).length,'cx-guests-'+x,filter===x?'primary':'')).join('')+'</div>'+panel('',table(['GUEST','ROOM','WHO PAYS','STATUS','DIETARY',''],rows));}
 else if(page==='documents'){title='Documents';body='<div class="grid2">'+['beo','contract'].map(id=>panel(id==='beo'?'Banquet Event Order (BEO)':'Contract','<p class="muted">'+(id==='beo'?'Version 2 · Updated Sep 12, 2026':'Signed electronically · Sep 22, 2026')+'</p>'+v2Pill(id==='beo'?'Final':'Signed')+'<div class="row mt">'+button('View','doc-'+id)+button('Download','download-'+id)+'</div>')).join('')+panel('Event agenda','<p class="muted">Updated Sep 22, 2026</p>'+v2Pill('Shared')+'<div class="mt">'+button('Download','cx-agenda')+'</div>')+panel('Group Block approval','<p class="muted">GBR-008 · Quote and booking confirmation</p>'+v2Pill('Confirmed')+'<div class="mt">'+button('View','portal-organizer-overview')+'</div>')+'</div>';}
 else if(page==='billing'){title='Invoices and payments';body='<div class="pickup-confirmed-columns">'+panel('Invoices',table(['INVOICE','DESCRIPTION','DUE','AMOUNT','STATUS',''],[['INV-00031','Deposit (50%)','Sep 22, 2026',money(t.deposit),v2Pill('Paid'),button('Receipt','download-invoice','link')],['INV-00031','Balance',dueDate(),money(groupBalance()),v2Pill(groupBalance()?'Due':'Paid'),button(groupBalance()?'Pay now':'Receipt',groupBalance()?'cx-group-pay':'download-invoice',groupBalance()?'primary':'link')]]))+'<div class="stack">'+panel('Summary',line('Rooms',money(t.rooms))+line('Meeting Hall and catering',money(t.space+t.addons))+line('Taxes',money(t.tax))+line('Original total',money(t.total))+(pickupCredit()?line('Individual room credits','−'+money(pickupCredit())):'')+line('Organizer invoice',money(groupInvoiceTotal()),'total')+line('Paid',money(t.deposit+(state.quote.balancePaid||0)))+line('Balance due',money(groupBalance()),'total'))+panel('Payment method','<p>Card · Visa ending '+(state.quote.cardLast4||'4242')+'</p><p class="hint">Used for the deposit on Sep 22, 2026</p><div class="mt">'+button('Change card','cx-group-card')+'</div>')+'</div></div>';}
 else if(page==='schedule'){title='Schedule and meals';body=panel('Schedule',table(['DAY','TIME','SESSION','LOCATION','GUESTS'],scheduleRows().map(x=>[...x,r.guests])))+'<div class="mt">'+panel('Meals',table(['MEAL','WHEN','GUESTS','DIETARY NEEDS','STATUS'],mealRows().map(x=>[x.meal,x.when,x.guests,esc(x.dietary),v2Pill(x.status)])))+'</div>';}
 else if(page==='invite'){title='Invite guests';body='<div class="pickup-confirmed-columns">'+panel('Share the group link','<p>Guests can choose a room from your blocked inventory and pay at the group rate.</p><div class="group-code">GBR-008</div><div class="row mt">'+button('Copy booking link','v2-copy','primary')+button('Email the code','v2-email-code')+'</div>')+panel('Room invitations',roomSlots().filter(s=>s.status==='Invited').map(s=>'<div class="invite-row"><div><b>'+esc(v2Full(s.guest))+'</b><small>'+esc(s.guest.email)+'</small></div>'+button('Resend','v2-slot-'+s.id)+'</div>').join('')+'<div class="mt">'+button('Send invites','v2-invites','primary')+'</div>')+'</div>';}
 else return connectedBase.organizer();
 const actions=page==='guests'?button('Import list','v2-import')+button('Export','cx-export')+button('Add guest','v2-add','primary'):page==='schedule'?button('Update meal counts','cx-meals'):'';return v2Page(v2Title(title,page==='overview'?'GBR-008 · '+dates()+' · Cedar Valley Retreat & Conference Center':page==='guests'?'Everyone staying with your group and how they are paying.':page==='billing'?'Payments for the venue, rooms and meals booked by the organizer.':page==='documents'?'Everything signed or shared for the retreat.':'What happens each day, and the meal counts for the venue team.',actions)+body);
}
function guestCharges(r){const rows=[[r.type+' · '+nights()+' nights',money(r.amount),v2Pill(r.paid?'Paid':'Due')],['Group meals and meeting hall','Included',v2Pill('Included')],...guestExtras(r).map(x=>[x.title,money(x.price*1.1),v2Pill((r.extrasPaid||0)>=extrasTotal(r)?'Paid':'Due')]),...requestsFor(r).filter(q=>q.status==='Confirmed').map(q=>[q.title,q.amount?money(q.amount):'Included',v2Pill(q.amount?'Added to stay':'Included')]),...ordersFor(r).map(o=>[o.id+' · '+o.items.map(x=>x.qty+'× '+x.title).join(', '),money(o.total),v2Pill(o.payment==='Room'?'Charged to room':'Paid')])];return table(['DESCRIPTION','AMOUNT','STATUS'],rows)+'<div class="mt">'+line('Total charges',money(stayTotal(r)))+line(r.organizerPaid?'Room paid by organizer':'Payments received',money(stayPaid(r)))+line('Balance due',money(stayBalance(r)),'total')+'</div>'+(stayBalance(r)?button('Pay balance '+money(stayBalance(r)),'cx-guest-pay','primary'):button('Download receipt','portal-download'));
}
guestPortal=function(){const page=state.ui.portalPage||'stay',r=portalGuest();if(!r)return connectedBase.guest();let title='',sub='',body='';
 if(page==='stay'){title='Welcome, '+r.guest.first;sub=r.type+' · '+dates()+' · '+state.request.organization;body=statCards([['Room',r.type.replace(' Room',''),r.assigned?'Room '+r.unit:'Room number at check-in'],['Check-in',dateLabel(state.request.start),'From 3:00 PM'],['Check-out',dateLabel(state.request.end),'By 11:00 AM'],['Reservation','#'+r.id,'Group GBR-008']])+'<div class="portal-overview-columns">'+panel('Your charges',line('Stay (paid at booking)',money(r.amount))+line('Group meals and meeting hall','Included')+line('Balance due',money(stayBalance(r)),'total')+'<div class="mt">'+button('View charges','portal-guest-charges')+'</div>',v2Pill(stayBalance(r)?'Balance due':'Paid in full'))+panel('Your check-in pass','<div class="pass-preview">'+'<div class="pass-code">'+img('a55f3.svg','Check-in QR','pass-small')+'<small>'+guestPassCode(r)+'</small></div>'+'<div><p class="muted">'+(r.checkedOut?'Your stay is checked out.':r.checkedIn?'You are checked in. Room '+esc(r.unit)+' · '+esc(r.waiver?.signedAt||'Arrival recorded'):'Show this pass at the front desk on '+dateLabel(state.request.start)+' to check in.')+'</p>'+button('Show pass','cx-pass')+'</div></div>')+'</div>'+requestsFor(r).filter(q=>q.status!=='New').map(q=>'<div class="pickup-callout mt"><b>'+q.title+' · '+q.status+'</b><p>'+esc(q.message)+'</p></div>').join('');}
 else if(page==='room'){title=r.paid?'Your assigned room':'Your room is held for you';sub=r.paid?'Room details and confirmation for your stay.':'Confirm it and pay for your own room at the group rate.';body='<div class="pickup-confirmed-columns">'+panel('Your stay','<div class="grid2">'+detail('Guest',esc(v2Full(r.guest)))+detail('Room',r.type)+detail('Dates',dates()+' · '+nights()+' nights')+detail('Group',esc(state.request.organization))+detail('Organizer',esc(name()))+detail('Room number',r.assigned?r.unit:'Assigned at check-in')+'</div>'+(r.paid?'<div class="mt">'+button(r.roomAccepted?'Room confirmed':'Confirm room','portal-confirm-room','primary',r.roomAccepted)+'</div>':'<div class="pickup-callout mt">Held until '+dateLabel(addDays(state.request.start,-13))+' · after that the room returns to the group</div>'))+panel('Your booking',line(money(roomRate(r.type))+' × '+nights()+' nights',money(roomRate(r.type)*nights()))+line('Taxes',money(r.amount-roomRate(r.type)*nights()))+line('Total',money(r.amount),'total')+'<div class="pickup-callout"><b>Group rate applied</b><small>Your room is reserved from the group block.</small></div>'+(r.paid?v2Pill(r.organizerPaid?'Paid by organizer':'Paid'):button('Confirm and pay '+money(r.amount),'portal-guest-payment','primary wide-btn')+button('I can’t attend','cx-decline-room','wide-btn')))+'</div>';}
 else if(page==='charges'||page==='payment'){title=page==='charges'?'Your charges':'Payment';sub='Charges and payments linked to Reservation #'+r.id;body='<div class="pickup-confirmed-columns">'+panel('Charges',guestCharges(r))+panel('Payment method','<p>'+(r.organizerPaid?'Room paid by the organizer':'Visa ending 4242')+'</p><p class="hint mt">Payments are simulated for this recording prototype.</p>')+'</div>';}
 else if(page==='schedule'){title='Your schedule';sub='Your retreat sessions, meals and confirmed activities.';body=panel('Schedule',table(['DAY','TIME','SESSION','LOCATION'],scheduleRows()))+'<div class="mt">'+panel('Your activities',requestsFor(r).length?table(['ACTIVITY','DATE AND TIME','STATUS'],requestsFor(r).map(q=>[q.title,q.when,v2Pill(q.status)])):'<p class="muted">No activities requested yet.</p>')+'</div>';}
 else if(page==='documents'){title='Documents';sub='Documents shared for your stay.';body='<div class="grid2">'+panel('Reservation confirmation','<p class="muted">#'+r.id+' · '+dates()+'</p><div class="row mt">'+button('View','portal-guest-stay')+button('Download','portal-download')+'</div>')+panel('Retreat schedule','<p class="muted">Sessions, group meals and activities</p><div class="row mt">'+button('View','portal-guest-schedule')+button('Download','cx-agenda')+'</div>')+panel('Guest stay waiver','<p class="muted">'+(r.waiver?'Signed at check-in by '+esc(r.waiver.name):'Sign at the front desk during check-in')+'</p><div class="mt">'+button('View','cx-view-waiver')+'</div>')+panel('Check-in pass','<p class="muted">Your personal arrival pass</p><div class="mt">'+button('View','cx-pass')+'</div>')+'</div>';}
 else if(page==='extras'){title='Add-ons';sub='Add activities, meals, a shuttle or extras to your stay. The venue team is notified.';const cat=ops().addonCategory,s=serviceById(ops().selectedService),existing=requestsFor(r).find(q=>q.serviceId===s?.id&&q.status!=='Declined');body='<div class="row mb">'+['Activities','Meals','Shuttle','Extras'].map(x=>button(x,'cx-category-'+x,cat===x?'active':'')).join('')+'</div><div class="addon-columns"><div class="stack">'+serviceCatalog.filter(x=>x.category===cat).map(x=>'<article class="service-option '+(s?.id===x.id?'selected':'')+'"><div class="service-thumb"></div><div><h3>'+x.title+'</h3><p>'+x.description+'</p>'+v2Pill(x.price?money(x.price)+' per person':'Included in your group booking')+'</div>'+button(s?.id===x.id?'Selected':x.price?'Request':'Add','cx-select-'+x.id,s?.id===x.id?'primary':'')+'</article>').join('')+'</div>'+panel('Your request',s?detail('Activity',s.title)+detail('Date and time',s.when)+detail('Guests','1 guest ('+esc(v2Full(r.guest))+')')+detail('Price',s.price?money(s.price)+' + 10% tax':'Included in your group booking')+'<p class="hint mt">The venue team receives your request and confirms it by message.</p>'+button(existing?existing.status==='New'?'Request sent':existing.status:'Request '+(cat==='Activities'?'activity':'service'),'cx-request-service','primary wide-btn',!!existing):'<p>Select a service.</p>')+'</div>';}
 else return connectedBase.guest();return v2Page((page==='stay'?designPortalTitle(title,sub,r.checkedOut?'Checked out':r.checkedIn?'Checked in':r.status):v2Title(title,sub))+body);
}
function serviceSentPage(){const q=ops().requests.find(q=>q.id===ops().lastRequest);return v2Page('<div class="pickup-confirmation"><span class="pickup-success">'+img('a79b9.svg')+'</span><h1>Request sent</h1><p>The venue team has been notified and will confirm by message.</p></div><div class="pickup-confirmed-columns">'+panel('Your request',detail('Activity',q.title)+detail('Date and time',q.when)+detail('Guest',esc(v2Full(q.guest))+' · '+q.unit)+detail('Price',q.amount?money(q.amount):'Included in your group booking'),v2Pill('Requested'))+panel('What happens next','<div class="portal-schedule-item"><b>Requested</b><p>Guest portal · '+q.id+'</p></div><div class="portal-schedule-item"><b>Venue team notified</b><p>Request Manager</p></div><div class="portal-schedule-item"><b>Confirmed</b><p>You will get a message</p></div>')+'</div><div class="row mt">'+button('Back to activities','portal-guest-extras')+button('View my stay','portal-guest-stay','primary')+'</div>');}
function serviceRequestList(){const rows=ops().requests.filter(q=>!ops().requestFilter||ops().requestFilter==='All'||q.status===ops().requestFilter).map(q=>[button(q.id,'cx-request-'+q.id,'link'),q.title,button(v2Full(q.guest),'cx-contact-'+q.guestKey,'link'),button('#'+q.reservationId,'v2-record-'+q.reservationId,'link'),q.when,badge(q.status),q.assigned]);return '<div class="admin service-admin">'+sfNav()+adminHeader('Request Manager','Service requests','Guest portal requests · '+ops().requests.filter(q=>q.status==='New').length+' new notifications')+'<div class="admin-main">'+statCards([['New',ops().requests.filter(q=>q.status==='New').length,'Waiting for staff'],['Confirmed',ops().requests.filter(q=>q.status==='Confirmed').length,'Guest notified'],['All requests',ops().requests.length,'Connected to reservations']])+'<section class="panel"><div class="row mb">'+['All','New','Confirmed','Declined'].map(x=>button(x,'cx-filter-'+x,ops().requestFilter===x?'primary':'')).join('')+'</div>'+table(['REQUEST','SERVICE','GUEST','RESERVATION','DATE AND TIME','STATUS','ASSIGNED TO'],rows)+'</section></div></div>';}
function serviceRequestDetail(){const q=ops().requests.find(q=>q.id===ops().currentRequest)||ops().requests[0],s=serviceById(q.serviceId);return '<div class="admin service-admin">'+sfNav()+adminHeader('',q.title,breadcrumbs([['Request Manager','cx-requests'],[q.id]])+'Requested in the guest portal',q.status==='New'?button('Decline','cx-service-decline')+button('Confirm request','cx-service-confirm','primary'):button('Message guest','cx-service-message'),q.status)+'<div class="admin-main request-layout"><div class="stack">'+panel('Request details','<div class="grid2">'+detail('Guest',button(v2Full(q.guest),'cx-contact-'+q.guestKey,'link'))+detail('Activity',q.title)+detail('Reservation',button('#'+q.reservationId+' · '+q.unit,'v2-record-'+q.reservationId,'link'))+detail('Date and time',q.when)+detail('Group',esc(state.request.organization))+detail('Guests / price','1 guest · '+(q.amount?money(q.amount):'Included in the group booking'))+'</div>')+panel('Activity',q.history.map(x=>'<div class="note-item">'+esc(x)+'</div>').join(''))+'</div><div class="stack">'+panel(q.status==='New'?'Next step':'Handled','<form id="cx-service-form">'+select('Assigned to','assigned',q.assigned,['Alex Rivera','Sam Patel','Jordan Reyes'])+textarea('Message to the guest','message',q.message||'Meet at the Main Lodge Lobby at 8:50 AM.')+(q.status==='New'?'<div class="row mt">'+button('Confirm request','cx-service-confirm','primary')+button('Decline','cx-service-decline')+'</div>':'')+'</form>')+panel('Capacity','<p>'+s.title+' · '+s.when+'</p><h2 class="mt">'+(s.booked+ops().requests.filter(x=>x.serviceId===s.id&&x.status==='Confirmed').length)+' of '+s.capacity+' spots booked</h2>')+'</div></div></div>';}
const posCategories=['Entrees','Sides','Appetizers','Desserts','Beverages','Snacks','Gift shop','Services'];
const posProducts=[['steak','Grilled Beef Steak',28,'Entrees'],['chicken','Grilled Chicken Breast',24,'Entrees'],['ribs','BBQ Pork Ribs',26,'Entrees'],['shrimp','Shrimp stir-fry with rice',22,'Entrees'],['lamb','Grilled Lamb Chops',32,'Entrees'],['salmon','Pan-Seared Salmon',27,'Entrees'],['garlic','Garlic Butter Shrimp',25,'Entrees'],['peppers','Stuffed bell peppers',18,'Entrees'],['coffee','Coffee',6.5,'Beverages'],['tea','Tea',4,'Beverages'],['juice','Fresh orange juice',7,'Beverages'],['water','Sparkling water',5,'Beverages'],['salad','Garden salad',8,'Sides'],['fries','Roasted potatoes',6,'Sides'],['soup','Soup of the day',9,'Appetizers'],['cake','Chocolate cake',10,'Desserts'],['bar','Granola bar',4,'Snacks'],['mug','Cedar Valley mug',15,'Gift shop'],['towel','Extra towel service',5,'Services']].map(([id,title,price,category])=>({id,title,price,category}));
const cartTotals=()=>{const p=ops(),subtotal=cent(p.cart.reduce((n,x)=>n+x.price*x.qty,0)),discount=Math.min(subtotal,Math.max(0,Number(p.discount)||0)),tax=cent((subtotal-discount)*.1);return {subtotal,discount,tax,tip:Math.max(0,Number(p.tip)||0),total:cent(subtotal-discount+tax+Math.max(0,Number(p.tip)||0))};};
function addPosItem(id,values={}){const p=posProducts.find(x=>x.id===id);requireState(p,'Item unavailable.');const qty=Number(values.qty||1);requireState(Number.isInteger(qty)&&qty>=1&&qty<=20,'Choose quantity 1–20.');ops().cart.push({...p,qty,options:values.temperature||(id==='coffee'?'Regular · Hot':''),seat:values.seat||'Seat 1',course:values.course||'Main course',note:values.note||''});save();}
function postPosOrder(payment){const p=ops(),r=activePosGuest(),t=cartTotals();requireState(Number.isFinite(Number(p.discount))&&Number(p.discount)>=0&&Number(p.discount)<=t.subtotal,'Discount cannot exceed the order subtotal.');requireState(r?.paid&&!r.checkedOut,'Choose an active confirmed stay.');requireState(p.cart.length,'Add items before checkout.');const order={id:'POS-'+p.nextOrder++,guestKey:guestKey(r),reservationId:r.id,items:JSON.parse(JSON.stringify(p.cart)),...t,payment,status:payment==='Room'?'Charged to room':'Paid',staff:p.staff,when:'Nov 12, 2026 · 7:42 PM'};p.orders.push(order);r.activities.push(order.id+' · '+order.status+' · '+money(order.total)+' · '+p.staff);p.lastOrder=order.id;p.cart=[];p.tip=0;p.discount=0;save();return order;}
function posFooter(){return '<nav class="pos-bottom">'+[['Availability Grid','cx-pos-availability'],['Reservations','cx-pos'],['Completed','cx-pos-completed'],['Invoices','cx-pos-invoices'],['Check-in','cx-pos-scan'],['Settings','cx-pos-settings']].map(([t,a])=>button(t,a,t==='Reservations'&&state.ui.admin.startsWith('pos')?'active':'')).join('')+'</nav>';}
function posShell(title,body,back='cx-pos'){return '<div class="pos-app"><header class="pos-top">'+(back?button('←',back,'link'):'<span></span>')+'<b>'+title+'</b><button data-action="cx-pms" aria-label="Close Cashier App">'+img('0cd94.svg')+'</button></header>'+body+posFooter()+'</div>';}
function posReservations(){const list=connectedGuests().filter(r=>r.paid&&(state.ui.admin==='pos-completed'?r.checkedOut:!r.checkedOut));return posShell('Reservations','<div class="pos-content"><div class="row between mb"><h1>Reservations</h1>'+button('Scan guest QR','cx-pos-scan')+'</div><input class="pos-search" name="pos-search" placeholder="Search guest, room or reservation"><div class="pos-reservations">'+list.map(r=>'<article class="pos-reservation"><h2>'+esc(v2Full(r.guest))+'</h2><p>RES-'+r.id+' · '+r.type+' · '+r.unit+'</p><p>'+dates()+' · '+(r.checkedOut?'Checked out':r.checkedIn?'Checked in':'Confirmed')+'</p><p>Balance '+money(stayBalance(r))+'</p><div class="row mt">'+button('Add charges','cx-pos-guest-'+r.id,'primary',r.checkedOut)+button(r.checkedIn?'Check-out':'Check-in',r.checkedIn?'cx-checkout-'+r.id:'cx-arrival-'+r.id,'',r.checkedOut)+button('Open record','v2-record-'+r.id)+'</div></article>').join('')+'</div></div>','');}
function posOrderPage(){const r=activePosGuest(),t=cartTotals();return posShell('#'+r.id,'<div class="pos-order"><aside class="pos-cart"><h3>'+esc(v2Full(r.guest))+' ('+esc(state.request.organization)+')</h3><p>'+r.type+' · '+r.unit+' · '+dates()+'</p><div class="pos-cart-tabs"><span>Stay</span><b>Additional charges</b></div><div class="pos-cart-lines">'+ops().cart.map((x,i)=>'<div><span>'+x.qty+'×</span><section><b>'+x.title+'</b><small>'+esc([x.options,x.seat,x.course,x.note].filter(Boolean).join(' · '))+'</small></section><b>'+money(x.qty*x.price)+'</b>'+button('×','cx-remove-item-'+i,'link')+'</div>').join('')+'</div><div class="pos-cart-total">'+line('Subtotal',money(t.subtotal))+(t.discount?line('Discount','−'+money(t.discount)):'')+line('Tax (10%)',money(t.tax))+line('Total',money(t.total),'total')+'<div class="row mt">'+button('Note','cx-pos-note')+button('Discount','cx-pos-discount')+'</div></div></aside><section class="pos-menu"><div class="row between"><h2>Dining Hall</h2><input name="pos-item-search" class="pos-item-search" placeholder="Search menu"></div><div class="pos-category-grid">'+posCategories.map((c,i)=>'<button style="--category-color:'+['#0eabd1','#ce2a51','#12af4d','#f48843','#15c6af','#f8bd3d','#e944da','#8055ff'][i]+'" class="'+(ops().category===c?'selected':'')+'" data-action="cx-pos-category-'+c+'">'+c+'</button>').join('')+'</div><div class="pos-item-grid">'+posProducts.filter(x=>x.category===ops().category).map(x=>'<button data-action="cx-item-'+x.id+'"><span>'+x.title+'</span><small>'+money(x.price)+'</small></button>').join('')+'</div><div class="pos-order-actions">'+button('Cancel','cx-pos-cancel')+button('Save','cx-pos-save')+button('Checkout →','cx-pos-checkout','primary')+'</div></section></div>');}
function posCheckoutPage(){const r=activePosGuest(),t=cartTotals();return posShell('Checkout','<div class="pos-amount">'+money(t.total)+'<small>total</small></div><div class="pos-checkout-columns"><section><h3>Adjust</h3>'+line('Tip',money(t.tip))+button('Add tip','cx-pos-tip','wide-btn')+line('Discount',money(t.discount))+button('Discount','cx-pos-discount','wide-btn')+'</section><section><h3>Items</h3>'+ops().cart.map(x=>line(x.qty+'× '+x.title,money(x.price*x.qty))).join('')+line('Tax (10%)',money(t.tax))+line('Total',money(t.total),'total')+'<p class="hint mt">Guest</p><p>'+esc(v2Full(r.guest))+' · '+r.type+' · '+r.unit+'</p></section><section><h3>Pay</h3>'+button('Charge to room','cx-charge-room','primary wide-btn')+'<p class="hint">'+esc(v2Full(r.guest))+' · Res #'+r.id+'</p>'+button('Cash','cx-charge-cash','wide-btn')+button('Card','cx-charge-card','wide-btn')+button('Print invoice','cx-print-cart','wide-btn')+'</section></div>','cx-pos-back');}
function posReceiptPage(){const o=ops().orders.find(o=>o.id===ops().lastOrder),r=activePosGuest();return posShell('Checkout','<div class="pos-result"><span class="pickup-success">'+img('4475f.svg')+'</span><h1>'+o.status+'</h1><p>'+esc(v2Full(r.guest))+' · '+r.type+' · '+r.unit+'</p><h2>'+money(o.total)+'</h2><p>Order '+o.id+' was added to Reservation #'+r.id+'</p><p>Balance due on the stay: '+money(stayBalance(r))+'</p><div class="row mt">'+button('New order','cx-pos-new','primary')+button('Done','cx-pos')+button('Open reservation','v2-record-'+r.id)+'</div></div>');}
function checkinPage(){const stage=ops().arrivalStage||'scan',r=activePosGuest();let body='';if(stage==='scan')body='<h1>Check-in</h1><p>Scan the guest’s QR pass to check them in</p><div class="pos-scan-columns"><section><div class="scan-window">'+img('c431f.svg','Demo scan QR')+(ops().scanPending?'<div class="scan-progress" role="status">Scanning guest pass…<progress max="100" aria-label="Scanning"></progress></div>':'')+'</div><form id="cx-scan-form">'+field('QR pass code','code','','text','placeholder="CV-0412" required')+'<div class="row mt">'+button(ops().scanPending?'Scanning…':'Start scan','cx-scan','primary',!!ops().scanPending)+button('Search reservation','cx-find-reservation')+'</div></form><p class="hint mt">Demo scan · no camera required.</p></section>'+panel('How it works','<p>1. Scan guest QR</p><p class="mt">2. Confirm stay and room</p><p class="mt">3. Sign waiver and check in</p>')+'</div>';else if(stage==='confirm')body='<h1>Confirm check-in</h1><p>Please confirm the details before recording the arrival</p><div class="pos-scan-columns">'+panel(esc(v2Full(r.guest)),detail('Reservation','#'+r.id+' · Group '+esc(state.request.organization))+detail('Stay',dates()+' · '+nights()+' nights')+detail('Room',r.type+' · '+r.unit)+detail('Balance due',money(stayBalance(r)))+'<div class="mt">'+button('Change room','cx-arrival-change')+'</div><h3 class="mt">Visit details</h3><p>Nov 12, 2026 · 3:45 PM</p><p>Check-in staff: '+esc(ops().staff)+' (Front desk)</p><div class="mt">'+button('Continue to waiver','cx-waiver','primary')+'</div>')+panel('How it works','<p>Confirm the guest, reservation and room. The signed waiver and check-in will appear in the connected record.</p>')+'</div>';else if(stage==='waiver')body='<h1>Stay waiver</h1><p>Please read and sign to complete check-in</p><div class="pos-scan-columns"><section>'+panel('1. Property rules','Guests agree to follow the venue rules, including quiet hours from 10:00 PM to 7:00 AM.')+'<div class="mt">'+panel('2. Responsibility','The venue is not responsible for items left unattended. Damage to rooms may be charged to the reservation.')+'</div><div class="mt">'+panel('3. Safety','Guests will follow posted safety instructions on trails and in shared spaces.')+'</div><form id="cx-waiver-form" class="mt">'+field('Guest signature','signature','','text','placeholder="Type your full name" required')+'<div class="waiver-signature" id="cx-waiver-preview">Sign here</div>'+check('I agree to the stay terms','agree',false,'required')+'<div class="mt">'+button('Sign and check in','cx-sign-checkin','primary')+'</div></form></section>'+panel('Demo check-in','The guest signature is saved on this local reservation record. No legal agreement is submitted.')+'</div>';else body='<div class="pos-result"><span class="pickup-success">'+img('50215.svg')+'</span><h1>Checked in</h1><p>'+esc(v2Full(r.guest))+' · '+r.type+' · '+r.unit+'</p><p>Reservation #'+r.id+' was updated for the whole team.</p><div class="row mt">'+button('Add charges','cx-pos-guest-'+r.id,'primary')+button('Open reservation','v2-record-'+r.id)+button('New scan','cx-pos-scan')+'</div></div>';return posShell('Check-in','<div class="pos-content">'+body+'</div>','cx-pos');}
function checkOutPage(){const r=activePosGuest();return posShell('Check-out','<div class="pos-content"><h1>'+(r.checkedOut?'Checked out':'Check-out')+'</h1><p>'+esc(v2Full(r.guest))+' · #'+r.id+' · '+r.type+' · '+r.unit+'</p><div class="pos-scan-columns">'+panel('Stay summary',guestCharges(r))+(r.checkedOut?panel('Completed','<p>The final invoice is paid and the stay is checked out.</p>'+button('Open reservation','v2-record-'+r.id,'primary')):panel('Complete check-out','<p>Collect the remaining balance before checking out.</p><div class="mt">'+button(stayBalance(r)?'Pay '+money(stayBalance(r))+' & check out':'Confirm check-out','cx-checkout-pay','primary')+'</div>'))+'</div></div>');}
function connectedTables(r){return '<h2 class="reservation-section-title">POS orders ('+ordersFor(r).length+')</h2>'+table(['ORDER','DATE & TIME','ITEMS','STAFF','STATUS','AMOUNT',''],ordersFor(r).map(o=>[o.id,o.when,o.items.map(x=>x.qty+'× '+x.title).join(', '),o.staff,badge(o.status),'<b>'+money(o.total)+'</b><p class="hint">'+money(o.subtotal)+' + Tax '+money(o.tax)+'</p>',button('View order','cx-order-'+o.id,'link')]))+'<h2 class="reservation-section-title">Services ('+requestsFor(r).length+')</h2>'+table(['SERVICE','DATE & TIME','SOURCE','STATUS','AMOUNT',''],requestsFor(r).map(q=>[q.title,q.when,'Added in the guest portal',badge(q.status),q.status==='Confirmed'?q.amount?money(q.amount):'Included':'Pending confirmation',button('View request','cx-request-'+q.id,'link')]))+'<h2 class="reservation-section-title">Signatures</h2>'+table(['DOCUMENT','SIGNER','STATUS',''],[['Group BEO / contract',name(),badge(state.quote.signature?'Signed':'Pending'),button('View','doc-contract','link')],['Guest stay waiver',r.waiver?esc(r.waiver.name):'—',badge(r.waiver?'Signed':'Pending'),button('View','cx-view-waiver','link')]]);}
individualDetailPage=function(){const r=currentIndividual();let html=connectedBase.detail();html=html.replace('<span>Grand Total</span><strong>'+money(r.amount+extrasTotal(r)),'<span>Grand Total</span><strong>'+money(stayTotal(r))).replace('<span>Balance Due</span><strong>'+money((r.paid?0:r.amount)+extrasTotal(r)-(r.extrasPaid||0)),'<span>Balance Due</span><strong>'+money(stayBalance(r)));html=html.replace(detail('Taxes',money(r.amount-roomRate(r.type)*nights())),detail('Taxes',money(cent(r.amount-roomRate(r.type)*nights()+extrasTotal(r)/11+serviceTotal(r)/11+ordersFor(r).reduce((n,o)=>n+o.tax,0)))));if((pickup().detailTab||'Details')==='Details')html=html.replace('<div class="reservation-add">',connectedTables(r)+'<div class="reservation-add">');if(r.checkedIn||r.checkedOut)html=html.replace('Group Block',badge(r.checkedOut?'Checked out':'Checked in')+' · Group Block');html=html.replace('<div class="reservation-meta">', '<div class="reservation-meta">');html=html.replace('data-action="v2-contact"','data-action="cx-contact-'+r.id+'"');if((pickup().detailTab)==='Payments')html=html.replace('</table>', '</table><div class="mt">'+line('Room payment',money(r.paid?r.amount:0))+line('Other payments',money(stayPaid(r)-(r.paid?r.amount:0)))+line('Balance due',money(stayBalance(r)))+'</div>');return html;};
individualListPage=function(){let html=connectedBase.list();for(const r of pickup().reservations){html=html.replace('<td>'+money(r.amount+extrasTotal(r))+'</td><td>'+money((r.paid?0:r.amount)+extrasTotal(r)-(r.extrasPaid||0))+'</td>','<td>'+money(stayTotal(r))+'</td><td>'+money(stayBalance(r))+'</td>');}return html;};
function contactRecord(){const r=individualById(ops().contactId||'00032')||roomSlots().filter(s=>s.guest).map(organizerPaidGuest).find(r=>guestKey(r)===ops().contactId)||activePosGuest();return '<div class="admin pickup-pms">'+sfNav()+adminHeader('',v2Full(r.guest),breadcrumbs([['Contacts','nav-Contacts'],[v2Full(r.guest)]])+'Horizon Foundation · '+esc(r.guest.email),button('Open reservation','v2-record-'+r.id,'primary'))+'<div class="admin-main"><div class="grid2">'+panel('Contact details',detail('Email',esc(r.guest.email))+detail('Phone',esc(r.guest.phone||'+1 415 555 0142'))+detail('Organization',esc(state.request.organization)))+panel('Connected stay',detail('Reservation',button('#'+r.id,'v2-record-'+r.id,'link'))+detail('Room',r.type+' · '+r.unit)+detail('Stay',dates())+detail('Balance due',money(stayBalance(r))))+'</div><section class="panel mt">'+connectedTables(r)+'<h2 class="reservation-section-title">History</h2>'+r.activities.map(a=>'<div class="note-item">'+esc(a)+'</div>').join('')+'</section></div></div>';}
function guestPassPage(){const r=portalGuest();return v2Page(v2Title('Check in at the front desk','Show this pass when you arrive. You can also keep it on your phone.')+'<div class="pickup-confirmed-columns">'+panel('Your check-in pass','<div class="pass-large">'+img('d633a.svg','Demo QR check-in pass')+'<h3>'+esc(v2Full(r.guest))+'</h3><p>'+r.type+' · '+dates()+'</p><div class="row mt">'+button('Add to wallet','cx-wallet')+button('Download','cx-download-pass')+'</div></div>')+panel('How it works','<div class="next-step"><span class="dot">1</span><p><b>Show your pass</b><br>Open this page or the email and show the QR code at the front desk.</p></div><div class="next-step"><span class="dot">2</span><p><b>Staff scan it</b><br>The team scans the code with the POS tablet and confirms your room.</p></div><div class="next-step"><span class="dot">3</span><p><b>You are checked in</b><br>Your reservation is updated and your room is ready.</p></div><div class="pickup-callout">Reservation #'+r.id+' · Group '+esc(state.request.organization)+'<small>Check-in opens '+dateLabel(state.request.start)+' at 3:00 PM</small></div>')+'</div>');}
mailboxMessages=function(){const msgs=connectedBase.messages(),person=mailboxPerson();if(person.role==='Guest'&&v2Active()){const r=pickup().reservations.find(r=>r.guest.email===person.email);if(r?.paid){msgs.unshift({id:'portal',subject:'Your guest portal · #'+r.id,preview:'Your stay, schedule, documents and charges.',heading:'Your personal guest portal',body:'Hi '+r.guest.first+', your personal portal has your room, schedule, documents and charges. You can also request activities and services.',cta:'Open guest portal',action:'mail-link-guest-'+r.id});msgs.unshift({id:'pass',subject:'Your check-in pass · '+guestPassCode(r),preview:'Show your pass at the front desk when you arrive.',heading:'Your check-in pass',body:'Hi '+r.guest.first+', your room is booked. Show your personal pass at the front desk on '+dateLabel(state.request.start)+'.',cta:'View my pass',action:'cx-mail-pass-'+r.id});for(const q of requestsFor(r).filter(q=>q.status!=='New'))msgs.unshift({id:q.id,subject:q.title+' · '+q.status,preview:q.message,heading:'Your request is '+q.status.toLowerCase(),body:q.message,cta:'View my schedule',action:'cx-mail-schedule-'+r.id});}}return msgs;};
demoBar=function(){let html=connectedBase.bar();html=html.replace(new RegExp('<button data-action="v2-start"[^>]*>Video 2</button>'),button('Video 2','v2-start',v2Active()&&!(state.ui.video>=3)?'video-active':'')+button('Video 3','cx-video3',state.ui.video===3?'video-active':'')+button('Video 4','cx-video4',state.ui.video===4?'video-active':''));if(state.ui.video>=3)html=html.replace('>VIDEO 2<','>VIDEO '+state.ui.video+'<');if(v2Active())html=html.replace('</div></div>', '</div></div>');if(v2Active())html+='<div class="connected-demo-nav">'+button('Service requests'+(ops().requests.filter(q=>q.status==='New').length?' ('+ops().requests.filter(q=>q.status==='New').length+' new)':''),'cx-requests')+button('Cashier App','cx-pos')+button('Connected record','cx-pms')+'</div>';return html;};
render=function(){const views={'service-list':serviceRequestList,'service-detail':serviceRequestDetail,'pos-list':posReservations,'pos-completed':posReservations,'pos-order':posOrderPage,'pos-checkout':posCheckoutPage,'pos-receipt':posReceiptPage,'pos-arrival':checkinPage,'pos-departure':checkOutPage,'connected-contact':contactRecord};if(state.ui.app==='admin'&&views[state.ui.admin]){$('#demo').innerHTML=demoBar();$('#app').innerHTML=views[state.ui.admin]();renderOverlay();return;}if(state.ui.app==='guest'&&['service-sent','guest-pass'].includes(state.ui.guest)){$('#demo').innerHTML=demoBar();$('#app').innerHTML=state.ui.guest==='service-sent'?serviceSentPage():guestPassPage();renderOverlay();return;}connectedBase.render();};
function connectedInvoice(r){return '<div class="connected-invoice"><h2>Invoice INV-'+r.id+'</h2><p>'+esc(v2Full(r.guest))+' · '+esc(r.guest.email)+'</p><p>'+dates()+' · '+r.type+' · '+r.unit+'</p><div class="mt">'+guestCharges(r)+'</div></div>';}
renderOverlay=function(){if(!modal?.startsWith('cx-'))return connectedBase.overlay();let title='',body='',footer='',wide=false;const p=ops(),r=v2Active()?activePosGuest():null;
 if(modal==='cx-item'){const item=posProducts.find(x=>x.id===p.item);title=item.title;body='<form id="cx-item-form">'+(item.id==='steak'?'<h3>Cooking temperature</h3><div class="temperature-options">'+['Rare','Med-Rare','Medium','Med-Well','Well','Pittsburgh / Charred','Blue','Char-grilled'].map(x=>'<label><input type="radio" name="temperature" value="'+x+'" '+(x==='Medium'?'checked':'')+'>'+x+'</label>').join('')+'</div><p class="hint mt">Included: 8 oz grass-fed beef · seasonal vegetables</p>':select('Style','temperature',item.id==='coffee'?'Regular · Hot':'Standard',item.id==='coffee'?['Regular · Hot','Decaf · Hot','Regular · Iced']:['Standard']))+'<div class="grid2 mt">'+field('Quantity','qty',1,'number','min="1" max="20" required')+select('Seat','seat','Seat 1',['Seat 1','Seat 2','Seat 3','Seat 4'])+select('Course','course','Main course',['Main course','Starter','Dessert','Drink'])+field('Sauce / note','note','','text','maxlength="120"')+'</div></form>';footer=button('Cancel','close-modal')+button('Add to order','cx-item-save','primary');wide=true;}
 else if(['cx-pos-tip','cx-pos-discount','cx-pos-note'].includes(modal)){title=modal==='cx-pos-tip'?'Add tip':modal==='cx-pos-discount'?'Discount':'Order note';body='<form id="cx-adjust-form">'+field(title,'value',modal==='cx-pos-tip'?p.tip:modal==='cx-pos-discount'?p.discount:p.note||'',modal==='cx-pos-note'?'text':'number',modal==='cx-pos-note'?'maxlength="200"':'min="0" step="0.01" required')+'</form>';footer=button('Cancel','close-modal')+button('Apply','cx-adjust-save','primary');}
 else if(modal==='cx-meals'){title='Update meal counts';body='<form id="cx-meals-form">'+mealRows().map((m,i)=>'<h3 class="mt">'+m.meal+' · '+m.when+'</h3><div class="grid2">'+field('Guests','guests-'+i,m.guests,'number','required min="1" max="60"')+field('Dietary needs','dietary-'+i,m.dietary,'text','maxlength="200"')+'</div>').join('')+'</form>';footer=button('Cancel','close-modal')+button('Save and notify venue','cx-meals-save','primary');wide=true;}
 else if(['cx-group-pay','cx-group-card','cx-guest-pay','cx-checkout-pay','cx-charge-card'].includes(modal)){title=modal==='cx-group-card'?'Change demo payment card':'Demo payment';const amount=modal==='cx-group-pay'?groupBalance():modal==='cx-charge-card'?cartTotals().total:modal==='cx-group-card'?0:stayBalance(modal==='cx-guest-pay'?portalGuest():r);body='<p class="payment-demo">No real charge. Use 4242 4242 4242 4242, expiry 12/29 and CVC 123.</p><h2 class="mt mb">'+money(amount)+'</h2><form id="cx-pay-form">'+(modal==='cx-checkout-pay'?select('Payment method','method','Saved card',['Saved card','New card','Cash']):'')+'<div id="cx-card-fields" '+(modal==='cx-checkout-pay'?'hidden':'')+'>'+field('Card holder','cardname',v2Full(r?.guest||{}),'text','required '+(modal==='cx-checkout-pay'?'disabled':''))+field('Card number','card','4242 4242 4242 4242','text','required autocomplete="off" '+(modal==='cx-checkout-pay'?'disabled':''))+'<div class="grid2 mt">'+field('Expiry','expiry','12/29','text','required autocomplete="off" '+(modal==='cx-checkout-pay'?'disabled':''))+field('CVC','cvc','123','password','required maxlength="3" autocomplete="off" '+(modal==='cx-checkout-pay'?'disabled':''))+'</div></div></form>';footer=button('Cancel','close-modal')+button(modal==='cx-group-card'?'Save demo card':'Confirm demo payment','cx-pay-save','primary');p.paymentPurpose=modal;}
 else if(modal==='cx-invoice'){const target=currentIndividual();title='Invoice INV-'+target.id;body=connectedInvoice(target);footer=button('Close','close-modal')+button('Download','portal-download','primary');wide=true;}
 else if(modal==='cx-order'){const o=p.orders.find(o=>o.id===p.currentOrder);title='Order '+o.id;body=detail('Reservation','#'+o.reservationId)+detail('Staff',o.staff)+detail('Payment',o.status)+table(['ITEM','QTY','OPTIONS','AMOUNT'],o.items.map(x=>[x.title,x.qty,esc(x.options),money(x.price*x.qty)]))+line('Tax',money(o.tax))+line('Total',money(o.total),'total');footer=button('Close','close-modal');wide=true;}
 else if(modal==='cx-view-waiver'){const target=state.ui.app==='guest'?portalGuest():currentIndividual();title='Guest stay waiver';body='<p>Property rules, responsibility and safety terms.</p>'+detail('Guest',esc(v2Full(target.guest)))+detail('Status',target.waiver?'Signed at check-in':'Not signed yet')+(target.waiver?'<div class="waiver-signature">'+esc(target.waiver.name)+'</div><p class="hint">Demo signature · Nov 12, 2026</p>':'<p class="hint">The guest signs during front-desk check-in.</p>');footer=button('Close','close-modal');}
 else if(modal==='cx-find'){title='Find reservation';body='<div class="stack">'+connectedGuests().filter(r=>r.paid&&!r.checkedOut).map(r=>button(v2Full(r.guest)+' · #'+r.id+' · '+r.unit,'cx-arrival-'+r.id)).join('')+'</div>';footer=button('Cancel','close-modal');}
 else return connectedBase.overlay();$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal '+(wide?'cx-wide':'')+'" role="dialog" aria-modal="true" aria-label="'+title+'"><header class="modal-header"><span>'+title+'</span>'+button('×','close-modal','modal-close')+'</header><div class="modal-content">'+body+'</div><footer class="modal-footer">'+footer+'</footer></section></div>';document.body.style.overflow='hidden';}
function demoCardValid(v){requireState(v.card.replace(/\D/g,'')==='4242424242424242','Use demo card 4242 4242 4242 4242.');requireState(/^\s*(0[1-9]|1[0-2])\s*\/\s*\d{2}\s*$/.test(v.expiry),'Use expiry MM/YY.');requireState(/^\d{3}$/.test(v.cvc),'Enter a three-digit demo CVC.');requireState(v.cardname.trim().length>2,'Enter the card holder name.');}
function formValues(id){const f=$(id);requireState(f&&f.reportValidity(),'Complete the required fields.');return Object.fromEntries(new FormData(f));}
handle=function(a,el){try{
 if(a==='cx-video3'){ensureLaterStory(3);return openMailbox('organizer');}if(a==='cx-video4'){ensureLaterStory(4);return navigate('admin','pos-list');}
 if(a==='portal-start-pickup'&&v2Active())return openOrganizerPortal('rooms');
 if(a==='nav-Request-Manager'&&v2Active()||a==='cx-requests'){requireState(v2Active(),'Start Video 2, 3 or 4 first.');return navigate('admin','service-list');}
 if(a==='nav-Contacts'&&v2Active()){ops().contactId=pickup().currentId||'00032';return navigate('admin','connected-contact');}
 if(a.startsWith('cx-contact-')){ops().contactId=a.slice(11);return navigate('admin','connected-contact');}
 if(a.startsWith('cx-request-')&&a!=='cx-request-service'){ops().currentRequest=a.slice(11);return navigate('admin','service-detail');}
 if(a.startsWith('cx-filter-')){ops().requestFilter=a.slice(10);save();render();return;}
 if(a.startsWith('cx-guests-')){ops().guestFilter=a.slice(10);save();render();return;}
 if(a.startsWith('cx-category-')){ops().addonCategory=a.slice(12);ops().selectedService=serviceCatalog.find(s=>s.category===ops().addonCategory).id;save();render();return;}
 if(a.startsWith('cx-select-')){ops().selectedService=a.slice(10);save();render();return;}
 if(a==='cx-request-service'){requestService(ops().selectedService);navigate('guest','service-sent');toast('Request sent. The venue team has been notified.');return;}
 if(a==='cx-service-confirm'||a==='cx-service-decline'){const v=formValues('#cx-service-form');resolveService(ops().currentRequest,a==='cx-service-confirm'?'Confirmed':'Declined',v.message,v.assigned);render();toast('Request '+(a==='cx-service-confirm'?'confirmed':'declined')+'. Guest notified.');return;}
 if(a==='cx-service-message'){ops().requests.find(q=>q.id===ops().currentRequest).message=formValues('#cx-service-form').message;save();toast('Message updated in the guest portal and inbox.');return;}
 if(a==='mail-link-payment-'+(portalGuest()?.id||'')||a.startsWith('mail-link-payment-')){state.ui.portalGuestId=a.slice(18);state.ui.portalRole='guest';state.ui.portalPage='room';return navigate('guest','guest-portal');}
 if(a==='cx-decline-room'){const r=portalGuest();requireState(r&&!r.paid,'A paid stay must be reviewed by staff.');const slot=slotById(r.slotId);Object.assign(slot,{guest:null,payer:null,status:'Open'});pickup().reservations=pickup().reservations.filter(x=>x.id!==r.id);pickup().activities.push(v2Full(r.guest)+' declined their invitation. Room returned to the group.');state.ui.portalGuestId=null;pickup().lastBooking=null;save();openMailbox();toast('Invitation declined. Your room returned to the group block.');return;}
 if(a==='cx-meals')return openModal(a);if(a==='cx-meals-save'){const v=formValues('#cx-meals-form');mealRows().forEach((m,i)=>{m.guests=Number(v['guests-'+i]);m.dietary=v['dietary-'+i].trim()||'—';m.status='Confirmed';});ops().mealNotification='Organizer updated meal counts and dietary needs.';(state.quote.notes??=[]).push(ops().mealNotification);modal=null;save();render();toast('Meal details updated. Venue team notified.');return;}
 if(a==='cx-export'){downloadBlob('Guest,Email,Room,Payer,Status\n'+roomSlots().filter(s=>s.guest).map(s=>[v2Full(s.guest),s.guest.email,s.unit,s.payer,s.status].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv','Group_GBR-008_Guests.csv');return;}
 if(a==='cx-agenda'){downloadBlob('Cedar Valley · '+state.request.group+'\n'+scheduleRows().map(x=>x.join(' · ')).join('\n'),'text/plain','Retreat_Agenda.txt');return;}
 if(a==='cx-pass')return navigate('guest','guest-pass');if(a.startsWith('cx-mail-pass-')){state.ui.portalGuestId=a.slice(13);state.ui.portalRole='guest';state.ui.portalPage='stay';return navigate('guest','guest-pass');}if(a.startsWith('cx-mail-schedule-'))return openGuestPortal('schedule',a.slice(17));
 if(a==='cx-wallet'||a==='cx-download-pass'){const r=portalGuest();downloadBlob('Cedar Valley demo check-in pass\n'+guestPassCode(r)+'\n'+v2Full(r.guest)+'\nReservation #'+r.id+'\n'+dates(),'text/plain','Checkin_Pass_'+r.id+'.txt');toast('Check-in pass downloaded.');return;}
 if(a==='cx-pms'){pickup().currentId=ops().reservationId||'00032';pickup().detailTab='Details';return navigate('admin','individual-detail');}
 if(a==='cx-pos'||a==='cx-pos-completed'){requireState(v2Active(),'Start Video 4 first.');return navigate('admin',a==='cx-pos'?'pos-list':'pos-completed');}
 if(a.startsWith('cx-pos-guest-')){ops().reservationId=a.slice(13);return navigate('admin','pos-order');}
 if(a.startsWith('cx-pos-category-')){ops().category=a.slice(16);save();render();return;}
 if(a.startsWith('cx-item-')&&a!=='cx-item-save'){ops().item=a.slice(8);return openModal('cx-item');}
 if(a==='cx-item-save'){addPosItem(ops().item,formValues('#cx-item-form'));modal=null;save();render();return;}
 if(a.startsWith('cx-remove-item-')){ops().cart.splice(Number(a.slice(15)),1);save();render();return;}
 if(['cx-pos-tip','cx-pos-discount','cx-pos-note','cx-group-pay','cx-group-card','cx-guest-pay','cx-view-waiver','cx-find-reservation'].includes(a))return openModal(a==='cx-find-reservation'?'cx-find':a);
 if(a==='cx-adjust-save'){const v=formValues('#cx-adjust-form').value;if(modal!=='cx-pos-note'){requireState(Number.isFinite(Number(v))&&Number(v)>=0,'Enter a valid non-negative amount.');if(modal==='cx-pos-discount')requireState(Number(v)<=cartTotals().subtotal,'Discount cannot exceed the order subtotal.');}if(modal==='cx-pos-tip')ops().tip=Number(v);if(modal==='cx-pos-discount')ops().discount=Number(v);if(modal==='cx-pos-note')ops().note=v;modal=null;save();render();return;}
 if(a==='cx-pos-save'){save();toast('Order draft saved for this stay.');return;}
 if(a==='cx-pos-cancel'){ops().cart=[];ops().tip=0;ops().discount=0;save();return navigate('admin','pos-list');}
 if(a==='cx-pos-checkout'){requireState(ops().cart.length,'Add items first.');return navigate('admin','pos-checkout');}if(a==='cx-pos-back')return navigate('admin','pos-order');
 if(a==='cx-charge-room'||a==='cx-charge-cash'){postPosOrder(a==='cx-charge-room'?'Room':'Cash');return navigate('admin','pos-receipt');}if(a==='cx-charge-card')return openModal(a);
 if(a==='cx-pos-new'){ops().cart=[];return navigate('admin','pos-order');}
 if(a.startsWith('cx-order-')){ops().currentOrder=a.slice(9);return openModal('cx-order');}
 if(a==='cx-pos-scan'){ops().arrivalStage='scan';return navigate('admin','pos-arrival');}
 if(a==='cx-scan'){if(ops().scanPending)return;const v=formValues('#cx-scan-form'),found=connectedGuests().find(r=>guestPassCode(r)===v.code.trim().toUpperCase());requireState(found,'QR not recognised. Search the reservation or enter the guest pass code.');requireState(!found.checkedOut,'This stay has already checked out.');const currentOps=ops();currentOps.scanPending=true;currentOps.reservationId=found.id;render();setTimeout(()=>{if(state.operations!==currentOps)return;currentOps.scanPending=false;if(state.ui.admin!=='pos-arrival')return;currentOps.arrivalStage='confirm';navigate('admin','pos-arrival');},5000);return;}
 if(a.startsWith('cx-arrival-')&&a!=='cx-arrival-change'){ops().reservationId=a.slice(11);requireState(!activePosGuest().checkedOut,'This stay has already checked out.');ops().arrivalStage='confirm';return navigate('admin','pos-arrival');}
 if(a==='cx-arrival-change'){pickup().currentId=activePosGuest().id;return connectedBase.handle('v2-change-room');}
 if(a==='cx-waiver'){ops().arrivalStage='waiver';save();render();return;}
 if(a==='cx-sign-checkin'){const v=formValues('#cx-waiver-form');requireState(v.agree,'Agree to the stay terms.');requireState(v.signature.trim().length>2,'Enter your signature.');const r=activePosGuest();r.waiver={name:v.signature.trim(),signedAt:'Nov 12, 2026 · 3:45 PM',staff:ops().staff};r.checkedIn=true;r.assigned=true;r.activities.push('Stay waiver signed by '+r.waiver.name+'.','Checked in · Nov 12, 2026 · 3:45 PM · '+ops().staff+' · QR scan at POS.');ops().arrivalStage='done';save();render();toast('Guest checked in. Reservation and signature updated.');return;}
 if(a.startsWith('cx-checkout-')&&!['cx-checkout-pay','cx-checkout-done'].includes(a)){ops().reservationId=a.slice(12);return navigate('admin','pos-departure');}
 if(a==='cx-checkout-pay'){if(stayBalance(activePosGuest()))return openModal(a);finishCheckOut();return;}
 if(a==='cx-pay-save'){const v=formValues('#cx-pay-form'),purpose=ops().paymentPurpose;if(purpose!=='cx-checkout-pay'||v.method==='New card')demoCardValid(v);else requireState(['Saved card','Cash'].includes(v.method),'Choose a payment method.');if(purpose==='cx-group-pay'){state.quote.balancePaid=cent((state.quote.balancePaid||0)+groupBalance());(state.quote.notes??=[]).push('Organizer balance paid by demo card.');}else if(purpose==='cx-group-card')state.quote.cardLast4='4242';else if(purpose==='cx-charge-card'){postPosOrder('Card');modal=null;return navigate('admin','pos-receipt');}else{const r=purpose==='cx-guest-pay'?portalGuest():activePosGuest();r.balancePayment=cent((r.balancePayment||0)+stayBalance(r));r.balancePaymentKind=v.method==='Cash'?'Cash':'Card';r.activities.push('Balance payment received · '+(r.balancePaymentKind==='Cash'?'Cash':'Card ending 4242')+'.');if(purpose==='cx-checkout-pay'){modal=null;finishCheckOut();return;}}modal=null;save();render();toast('Payment received. Invoice updated.');return;}
 if(a==='v2-check-in'){ops().reservationId=currentIndividual().id;ops().arrivalStage='confirm';return navigate('admin','pos-arrival');}
 if(a==='v2-check-out'){ops().reservationId=currentIndividual().id;return navigate('admin','pos-departure');}
 if(a==='v2-invoice'){return openModal('cx-invoice');}
 if(a==='cx-pos-availability')return connectedBase.handle('nav-Availability');if(a==='cx-pos-invoices'){pickup().currentId=activePosGuest().id;return openModal('cx-invoice');}if(a==='cx-pos-settings'){return;}
 if(a==='cx-print-cart'){downloadBlob('Cedar Valley POS draft\n'+ops().cart.map(x=>x.qty+'× '+x.title+' '+money(x.price*x.qty)).join('\n')+'\nTotal '+money(cartTotals().total),'text/plain','POS_Draft.txt');return;}
 return connectedBase.handle(a,el);
 }catch(e){toast(e.message,true);}};
function finishCheckOut(){const r=activePosGuest();requireState(!stayBalance(r),'Pay the outstanding balance before checkout.');requireState(r.checkedIn,'Check in the guest before checkout.');r.checkedOut=true;r.activities.push('Checked out · Nov 15, 2026 · 10:40 AM · '+ops().staff+'. Final invoice paid.');save();navigate('admin','pos-departure');toast('Checked out. Final invoice paid.');}
document.addEventListener('input',e=>{if(e.target.name==='signature'&&e.target.closest('#cx-waiver-form'))$('#cx-waiver-preview').textContent=e.target.value||'Sign here';if(e.target.name==='pos-search')document.querySelectorAll('.pos-reservation').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if(e.target.name==='pos-item-search')document.querySelectorAll('.pos-item-grid button').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
document.addEventListener('submit',e=>{const a={'cx-scan-form':'cx-scan','cx-item-form':'cx-item-save','cx-waiver-form':'cx-sign-checkin','cx-pay-form':'cx-pay-save','cx-meals-form':'cx-meals-save'}[e.target.id];if(a){e.preventDefault();handle(a);}});
/* Updated video 1 billing and BEO send-for-signature preview. */
totals=function(q=state.quote||wizard){const t=connectedBase.totals(q);if(!q)return t;const raw=Number(q.discount||0),discount=Math.min(t.subtotal,Math.max(0,q.discountType==='Percentage'?t.subtotal*raw/100:raw));const subtotal=cent(t.subtotal-discount),tax=q.tax?cent(subtotal*.1):0,total=cent(subtotal+tax);return {...t,beforeDiscount:t.subtotal,discount,subtotal,tax,total,deposit:cent(total*.5)};};
const totalLinesOriginal=totalLines;
totalLines=function(q=state.quote||wizard){const t=totals(q);return line('Amount total',money(t.beforeDiscount||t.subtotal))+(t.discount?line('Discount','−'+money(t.discount)):'')+line('Tax ('+(q.tax?'10':'0')+'%)',money(t.tax))+line('Grand Total',money(t.total),'total');};
quoteLines=function(q=state.quote||wizard){return connectedBase.quoteLines(q)+(totals(q).discount?line('Discount','−'+money(totals(q).discount)):'');};
wizardBody=function(){let html=connectedBase.wizardBody();if(wizard.step===3)html=html.replace('<p class="hint mt">','<div class="grid2 mt">'+select('Discount type','discountType',wizard.discountType||'Fixed amount',['Fixed amount','Percentage'])+field('Discount','discount',wizard.discount||0,'number','min="0" step="0.01" required')+'</div><p class="hint mt">');return html;};
captureWizard=function(){connectedBase.captureWizard();if(wizard?.step===3){const f=$('#wizard-form');wizard.discount=Number(f.elements.discount.value)||0;wizard.discountType=f.elements.discountType.value;requireState(wizard.discountType!=='Percentage'||wizard.discount<=100,'Percentage discount cannot exceed 100.');requireState(wizard.discount<= (wizard.discountType==='Percentage'?100:connectedBase.totals(wizard).subtotal),'Discount cannot exceed the booking subtotal.');}};
function beoPreview(){const tab=ops().beoTab||'beo';return '<div class="admin beo-preview-page">'+sfNav()+adminHeader('','Banquet Event Order',breadcrumbs([['Group Block GBR-008','open-block'],['Documents']])+'Version 2 · Updated Sep 12, 2026 · Preview as the client will see it',button('Edit BEO','cx-edit-beo')+button('Download','download-beo')+button('Send for e-signature','cx-send-sign','primary'),state.quote.signature?'Signed':state.quote.signingSent?'Sent':'Draft')+'<div class="admin-main request-layout"><section class="panel"><div class="row document-tabs">'+[['BEO','beo'],['Contract','contract'],['Agenda','agenda']].map(([t,a])=>button(t,'cx-beo-tab-'+a,tab===a?'primary':'')).join('')+'</div><div class="beo-paper">'+(tab==='agenda'?'<h2>Event agenda</h2>'+table(['DAY','TIME','SESSION','LOCATION'],scheduleRows()):documentHTML(tab))+'</div></section><div class="stack">'+panel('E-signature','<form id="cx-esign-form"><h3>Documents to sign</h3>'+check('BEO_GBR-008.pdf','beo',true)+check('Contract_GBR-008.pdf','contract',true)+'<h3 class="mt">Signers (in order)</h3>'+detail('Client',esc(name())+' · '+esc(state.request.email))+detail('Venue','Jordan Reyes · events@cedarvalley.example')+textarea('Message to the client','message',state.quote.beoMessage||'Hi Maya, please review the BEO and sign the contract to confirm your retreat. The deposit is paid in the next step.')+'<div class="mt">'+select('Reminder','reminder','After 3 days if unsigned',['After 3 days if unsigned','After 7 days if unsigned','No reminder'])+'</div><div class="mt">'+button('Send for e-signature','cx-send-sign','primary')+'</div></form>')+panel('After you send','<p>• The client gets a personal link to review and sign.</p><p class="mt">• Signed documents and signer status stay connected to the group booking.</p>')+'</div></div></div>';}
const fourRender=render,fourHandle=handle,fourOverlay=renderOverlay,fourMessages=mailboxMessages;
render=function(){if(state.ui.app==='admin'&&state.ui.admin==='beo-preview'){$('#demo').innerHTML=demoBar();$('#app').innerHTML=beoPreview();renderOverlay();return;}fourRender();};
handle=function(a,el){try{if(a==='doc-beo'&&state.ui.app==='admin'&&state.quote)return navigate('admin','beo-preview');if(a.startsWith('cx-beo-tab-')){ops().beoTab=a.slice(11);save();render();return;}if(a==='cx-edit-beo')return openModal(a);if(a==='cx-beo-save'){const v=formValues('#cx-beo-edit');state.quote.beoMessage=v.message;state.quote.beoNotes=v.notes;modal=null;save();render();toast('BEO updated.');return;}if(a==='cx-send-sign'){const v=formValues('#cx-esign-form');requireState(v.beo&&v.contract,'Include both BEO and contract.');state.quote.beoMessage=v.message;state.quote.signingSent=true;state.quote.reminder=v.reminder;addEvent('BEO and contract sent for e-signature to '+state.request.email+'.','Sam Patel');save();render();toast('Email sent with personal signing link.');return;}if(a==='portal-download'||a==='v2-download'){const r=state.ui.app==='guest'?portalGuest()||individualById(pickup().lastBooking):currentIndividual();return downloadStayPDF(r);}return fourHandle(a,el);}catch(e){toast(e.message,true);}};
renderOverlay=function(){if(modal!=='cx-edit-beo')return fourOverlay();$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Edit BEO"><header class="modal-header">Edit BEO'+button('×','close-modal','modal-close')+'</header><div class="modal-content"><form id="cx-beo-edit">'+textarea('Event notes','notes',state.quote.beoNotes||state.request.special)+textarea('Message to the client','message',state.quote.beoMessage||'Please review the BEO and sign the contract.')+'</form></div><footer class="modal-footer">'+button('Cancel','close-modal')+button('Save BEO','cx-beo-save','primary')+'</footer></section></div>';document.body.style.overflow='hidden';};
mailboxMessages=function(){const msgs=fourMessages();if(mailboxPerson().role==='Organizer'&&state.quote?.signingSent)msgs.unshift({id:'esign',subject:'Please review and sign · BEO and contract · GBR-008',preview:state.quote.beoMessage,heading:'Your BEO and contract are ready to sign',body:state.quote.beoMessage,cta:'Review and sign',action:'mail-link-quote'});return msgs;};
function downloadStayPDF(r){const lines=['CEDAR VALLEY RETREAT & CONFERENCE CENTER','Invoice INV-'+r.id+' - Reservation #'+r.id,v2Full(r.guest),r.guest.email,r.type+' - Room '+r.unit,dates(),r.checkedOut?'Checked out':r.checkedIn?'Checked in':'Confirmed','Room (including tax): '+money(r.amount),...guestExtras(r).map(x=>x.title+': '+money(x.price*1.1)),...requestsFor(r).filter(q=>q.status==='Confirmed').map(q=>q.title+': '+money(q.amount)),...ordersFor(r).map(o=>o.id+': '+o.items.map(x=>x.qty+'x '+x.title).join(', ')+' - '+money(o.total)),'Total: '+money(stayTotal(r)),'Payments: '+money(stayPaid(r)),'Balance due: '+money(stayBalance(r)),r.waiver?'Stay waiver signed: '+r.waiver.name:'Stay waiver: pending','Demo document - no real payment.'];const ascii=s=>s.replace(/[^\x20-\x7e]/g,'-').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');const stream='BT /F1 10 Tf 16 TL 45 790 Td '+lines.map((x,i)=>(i?'T* ':'')+'('+ascii(x)+') Tj').join('\n')+' ET';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];let pdf='%PDF-1.4\n',offsets=[];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n';});const xref=pdf.length;pdf+='xref\n0 6\n0000000000 65535 f \n'+offsets.map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';downloadBlob(pdf,'application/pdf','Invoice_'+r.id+'.pdf');}
render();

document.addEventListener('change',e=>{if(e.target.name==='method'&&e.target.closest('#cx-pay-form')){const fields=document.querySelector('#cx-card-fields'),show=e.target.value==='New card';fields.hidden=!show;fields.querySelectorAll('input').forEach(input=>input.disabled=!show);}});
